import{_ as i,r as t,o as l,c as r,e,a as n,s as o,d as s}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Vue Report Widgets - October CMS - 4.x","titleTemplate":false,"description":"A dashboard widget powered by Vue.js","frontmatter":{"subtitle":"A dashboard widget powered by Vue.js"},"headers":[{"level":2,"title":"Creating Custom Dashboard Widgets","slug":"creating-custom-dashboard-widgets","link":"#creating-custom-dashboard-widgets","children":[{"level":3,"title":"Creating and Registering Custom Widgets","slug":"creating-and-registering-custom-widgets","link":"#creating-and-registering-custom-widgets","children":[]},{"level":3,"title":"Server-Side Class","slug":"server-side-class","link":"#server-side-class","children":[]},{"level":3,"title":"Client-Side Component","slug":"client-side-component","link":"#client-side-component","children":[]},{"level":3,"title":"Registering a Widget","slug":"registering-a-widget","link":"#registering-a-widget","children":[]},{"level":3,"title":"Handling Events","slug":"handling-events","link":"#handling-events","children":[]}]}],"relativePath":"4.x/extend/dashboards/vue-report-widgets.md","filePath":"4.x/extend/dashboards/vue-report-widgets.md"}'),u={name:"4.x/extend/dashboards/vue-report-widgets.md"};function d(k,a,g,h,m,w){const p=t("pre-heading"),c=t("post-heading");return l(),r("div",null,[e(p),a[0]||(a[0]=n("h1",null,"Vue Report Widgets",-1)),e(c),a[1]||(a[1]=o(`<h2 id="creating-custom-dashboard-widgets"><a href="#creating-custom-dashboard-widgets" class="header-anchor">#</a> Creating Custom Dashboard Widgets</h2><p>The dashboard system enables developers to create custom configurable widgets, offering functionality that extends beyond the capabilities of the built-in widgets. These custom widgets can be designed with any appearance and functionality, including the ability to fetch data and handle events through AJAX requests.</p><h3 id="creating-and-registering-custom-widgets"><a href="#creating-and-registering-custom-widgets" class="header-anchor">#</a> Creating and Registering Custom Widgets</h3><p>Dashboard widgets use the October CMS Vue framework. The framework simplifies the development of both server-side and client-side parts.</p><p>In this documentation, we will create a simple component that displays the current time and includes a button. The button&#39;s click action will be handled on the server using AJAX.</p><p><img src="https://raw.githubusercontent.com/octobercms/docs/develop/images/dashboards/widget-example.webp" alt="image"></p><p>Dashboard widgets should be placed in the <code>vuecomponents</code> directory located in the root directory of a plugin, for example, <code>author/plugin/vuecomponents</code>. Each component must include a PHP file for server-side implementation, a JavaScript file for the Vue component, and a PHP file for the Vue template. Below is an example of the file structure for a widget. Note that the names of the CSS, JavaScript, and partial files are derived from the widget’s class file name:</p><pre class="dir-container"><code><p>├── <code>vuecomponents</code>
|   ├── mycustomwidget
|   |   └── assets
|   |       └── css
|   |           └── mycustomwidget.css  <em>← StyleSheet File</em>
|   |       └── js
|   |           └── mycustomwidget.js  <em>← JavaScript File</em>
|   |   └── partials
|   |       └── _mycustomwidget.php  <em>← Partial File</em>
|   └── MyCustomWidget.php  <em>← Vue Widget Class</em></p>
</code></pre><h3 id="server-side-class"><a href="#server-side-class" class="header-anchor">#</a> Server-Side Class</h3><p>The server code for a dashboard widget must define a class that extends <code>Dashboard\\Classes\\VueReportWidgetBase</code>. The only required method that a widget class needs to implement is <code>getData</code>. Below is the initial implementation of the class (MyCustomWidget.php):</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>MyPlugin<span class="token punctuation">\\</span>VueComponents</span><span class="token punctuation">;</span>

<span class="token keyword">use</span> <span class="token package">Dashboard<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>VueReportWidgetBase</span><span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">Dashboard<span class="token punctuation">\\</span>Classes<span class="token punctuation">\\</span>ReportFetchData</span><span class="token punctuation">;</span>
<span class="token keyword">use</span> <span class="token package">Carbon<span class="token punctuation">\\</span>Carbon</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">MyCustomWidget</span> <span class="token keyword">extends</span> <span class="token class-name">VueReportWidgetBase</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * @var string componentName is the Vue component tag name.
     */</span>
    <span class="token keyword">protected</span> <span class="token variable">$componentName</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;acme-myplugin-vuecomponents-mycustomwidget&#39;</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">getData</span><span class="token punctuation">(</span><span class="token class-name type-declaration">ReportFetchData</span> <span class="token variable">$data</span><span class="token punctuation">)</span><span class="token punctuation">:</span> <span class="token keyword return-type">mixed</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token punctuation">[</span>
            <span class="token string single-quoted-string">&#39;current_time&#39;</span> <span class="token operator">=&gt;</span> <span class="token class-name static-context">Carbon</span><span class="token operator">::</span><span class="token function">now</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">format</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Y-m-d H:i:s&#39;</span><span class="token punctuation">)</span>
        <span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The <code>VueReportWidgetBase</code> class extends <code>System\\Classes\\VueComponentBase</code> and provides the dashboard-specific functionality needed for report widgets. The <code>$componentName</code> property is required and defines the Vue component tag name. The convention is to use the fully qualified class name in lowercase with backslashes replaced by hyphens (e.g., <code>Acme\\MyPlugin\\VueComponents\\MyCustomWidget</code> becomes <code>acme-myplugin-vuecomponents-mycustomwidget</code>).</p><h3 id="client-side-component"><a href="#client-side-component" class="header-anchor">#</a> Client-Side Component</h3><p>The Vue component for the widget must be defined as an ES module in the assets/js directory. The component uses <code>export default</code> and extends the base widget class. Example component code (assets/js/mycustomwidget.js):</p><div class="language-js extra-class"><pre class="language-js"><code><span class="token keyword">import</span> WidgetBase <span class="token keyword">from</span> <span class="token string">&#39;../../../../../../../modules/dashboard/vuecomponents/dashboard/assets/js/widget-base.js&#39;</span><span class="token punctuation">;</span>

<span class="token keyword">export</span> <span class="token keyword">default</span> <span class="token punctuation">{</span>
    <span class="token keyword">extends</span><span class="token operator">:</span> WidgetBase<span class="token punctuation">,</span>
    <span class="token function-variable function">data</span><span class="token operator">:</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token punctuation">{</span>
        <span class="token punctuation">}</span>
    <span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token literal-property property">methods</span><span class="token operator">:</span> <span class="token punctuation">{</span>
        <span class="token function-variable function">useCustomData</span><span class="token operator">:</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token keyword">return</span> <span class="token boolean">true</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span><span class="token punctuation">,</span>

        <span class="token function-variable function">makeDefaultConfigAndData</span><span class="token operator">:</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token keyword">this</span><span class="token punctuation">.</span>widget<span class="token punctuation">.</span>configuration<span class="token punctuation">.</span>title <span class="token operator">=</span> <span class="token string">&#39;My Custom Widget&#39;</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span><span class="token punctuation">,</span>

        <span class="token function-variable function">getSettingsConfiguration</span><span class="token operator">:</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
            <span class="token keyword">const</span> result <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">{</span>
                <span class="token literal-property property">property</span><span class="token operator">:</span> <span class="token string">&quot;title&quot;</span><span class="token punctuation">,</span>
                <span class="token literal-property property">title</span><span class="token operator">:</span> <span class="token string">&quot;Title&quot;</span><span class="token punctuation">,</span>
                <span class="token literal-property property">type</span><span class="token operator">:</span> <span class="token string">&quot;string&quot;</span><span class="token punctuation">,</span>
            <span class="token punctuation">}</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

            <span class="token keyword">return</span> result<span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">;</span>
</code></pre></div><p>The component is automatically registered by the <code>VueMaker</code> trait when the widget&#39;s PHP class is loaded. The template is injected from the partial file, so you don&#39;t need to specify a <code>template</code> property in the JavaScript.</p><p>Widget Vue components must include all the methods outlined in the example code. Specifically:</p>`,17)),a[2]||(a[2]=n("ul",null,[n("li",null,[n("code",null,"useCustomData"),s(" - this method must return "),n("code",null,"true"),s(" to inform the dashboard system that the component manages its own data cycle.")]),n("li",null,[n("code",null,"makeDefaultConfigAndData"),s(" - sets the default widget configuration. In our example, we assign the widget title using direct assignment (Vue 3's Proxy-based reactivity makes this reactive automatically). The configuration object's keys are arbitrary and intended for the widget's internal use. We will later demonstrate how to access the widget configuration in the component template. In the server-side code, the widget configuration can be accessed in the "),n("code",null,"getData"),s(" method via the "),n("code",null,"widgetConfig"),s(" argument.")]),n("li",null,[n("code",null,"getSettingsConfiguration"),s(" - provides the configuration for the widget’s settings form. The configuration is defined using JavaScript objects and aligns with the "),n("a",{href:"https://docs.octobercms.com/3.x/element/inspector-types.html",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[s("Inspector fields configuration"),n("span",null,[n("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[n("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),s(),n("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),s(),n("span",{class:"sr-only"},"(opens new window)")])]),s(".")])],-1)),a[3]||(a[3]=o(`<p>The component Vue template must be defined in a partial file located in the <code>partials</code> directory, as mentioned above. Below is a basic implementation of a component template (partials/_mycustomwidget.php):</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>widget-body<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h3</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>widget-title<span class="token punctuation">&quot;</span></span> <span class="token attr-name">v-text</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>widget.configuration.title<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h3</span><span class="token punctuation">&gt;</span></span>

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">v-if</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>!loading<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Current server time: <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>span</span> <span class="token attr-name">v-if</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>fullWidgetData<span class="token punctuation">&quot;</span></span> <span class="token attr-name">v-text</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>fullWidgetData.data.current_time<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>span</span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span> <span class="token attr-name">v-else</span><span class="token punctuation">&gt;</span></span>Loading...<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>The template illustrates how to retrieve the <code>title</code> property from the widget configuration, previously set in the <code>makeDefaultConfigAndData</code> method.</p><p>It also demonstrates accessing the <code>loading</code> property, supplied by the dashboard system. This property switches to <code>true</code> during data loading AJAX requests, handled by the dashboard. These requests can be triggered by changes in component configuration or when the user selects a date range on the dashboard. You can leverage the <code>loading</code> property to indicate the widget&#39;s loading status.</p><p>Lastly, the template guides you on accessing server-provided data using the <code>fullWidgetData.data</code> structure.</p><h3 id="registering-a-widget"><a href="#registering-a-widget" class="header-anchor">#</a> Registering a Widget</h3><p>Dashboard widgets must be registered in the plugin registration file (Plugin.php), using the <code>widgets</code> key of the <code>registerDashboards</code> method. The key should contain an array with the widget classes in the keys and widget configuration (label, group, and required permissions) in the values.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerDashboards</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;widgets&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
            <span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>October<span class="token punctuation">\\</span>Test<span class="token punctuation">\\</span>VueComponents<span class="token punctuation">\\</span>MyCustomWidget</span><span class="token operator">::</span><span class="token keyword">class</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span>
                <span class="token string single-quoted-string">&#39;label&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Custom Widget&#39;</span><span class="token punctuation">,</span>
                <span class="token string single-quoted-string">&#39;group&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Acme Author&#39;</span>
            <span class="token punctuation">]</span>
        <span class="token punctuation">]</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>The label and group properties are the widget&#39;s name and the author&#39;s name. These will be displayed in the Dashboard user interface, particularly in the Create Widget menu. Once the widget is registered, you can add it to the dashboard:</p><p><img src="https://raw.githubusercontent.com/octobercms/docs/develop/images/dashboards/adding-widget.webp" alt="image"></p><p>When you add a widget, its Settings form will automatically open:</p><p><img src="https://raw.githubusercontent.com/octobercms/docs/develop/images/dashboards/config-widget.webp" alt="image"></p><h3 id="handling-events"><a href="#handling-events" class="header-anchor">#</a> Handling Events</h3><p>Dashboard widgets can trigger and handle events using the built-in AJAX framework. Our demo widget includes a button. We will create a handler, so when the button is clicked, the server code returns a random number to be displayed in the widget body.</p><p>First, the button must be defined in the component template. The code below defines a button and an element for displaying the value returned by the server:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token operator">&lt;</span>button
    <span class="token keyword">class</span><span class="token operator">=</span><span class="token string double-quoted-string">&quot;btn btn-primary&quot;</span>
    <span class="token punctuation">:</span>disabled<span class="token operator">=</span><span class="token string double-quoted-string">&quot;loadingButtonData&quot;</span>
    @click<span class="token operator">.</span>stop<span class="token operator">.</span>prevent<span class="token operator">=</span><span class="token string double-quoted-string">&quot;onButtonClick&quot;</span>
<span class="token operator">&gt;</span>Click me<span class="token operator">&lt;</span><span class="token operator">/</span>button<span class="token operator">&gt;</span>
<span class="token operator">&lt;</span>span v<span class="token operator">-</span>text<span class="token operator">=</span><span class="token string double-quoted-string">&quot;buttonClickResult&quot;</span><span class="token operator">&gt;</span><span class="token operator">&lt;</span><span class="token operator">/</span>span<span class="token operator">&gt;</span>
</code></pre></div><p>The <code>loadingButtonData</code> and <code>buttonClickResult</code> values are not yet available and need to be defined in the Vue component of the widget:</p><div class="language-jsx extra-class"><pre class="language-jsx"><code><span class="token function-variable function">data</span><span class="token operator">:</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">{</span>
        <span class="token literal-property property">buttonClickResult</span><span class="token operator">:</span> <span class="token keyword">null</span><span class="token punctuation">,</span>
        <span class="token literal-property property">loadingButtonData</span><span class="token operator">:</span> <span class="token boolean">false</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">,</span>
</code></pre></div><p>It&#39;s also necessary to create the <code>onButtonClick</code> method. This method utilizes the widget’s <code>request</code> method from the base widget Vue component. It sets <code>loadingButtonData</code> to true, signaling the start of loading. Upon receiving the server&#39;s response, the method updates <code>buttonClickResult</code> with the <code>result</code> property from the response. Details on creating a server-side handler will be provided later. The method includes <code>some_var</code> in the request data, which is not utilized in our current server implementation but may be useful in other scenarios. On the server, <code>some_var</code> value can be accessed using the <code>extraData</code> handler argument.</p><div class="language-jsx extra-class"><pre class="language-jsx"><code><span class="token function-variable function">onButtonClick</span><span class="token operator">:</span> <span class="token keyword">async</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">this</span><span class="token punctuation">.</span>loadingButtonData <span class="token operator">=</span> <span class="token boolean">true</span><span class="token punctuation">;</span>
    <span class="token keyword">this</span><span class="token punctuation">.</span>buttonClickResult <span class="token operator">=</span> <span class="token keyword">null</span><span class="token punctuation">;</span>
    <span class="token keyword">try</span> <span class="token punctuation">{</span>
        <span class="token keyword">const</span> response <span class="token operator">=</span> <span class="token keyword">await</span> <span class="token keyword">this</span><span class="token punctuation">.</span><span class="token function">request</span><span class="token punctuation">(</span><span class="token string">&#39;onGetSomeData&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">{</span>
            <span class="token literal-property property">some_var</span><span class="token operator">:</span> <span class="token string">&quot;some value&quot;</span>
        <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token keyword">this</span><span class="token punctuation">.</span>buttonClickResult <span class="token operator">=</span> response<span class="token punctuation">.</span>result<span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
    <span class="token keyword">catch</span> <span class="token punctuation">(</span>err<span class="token punctuation">)</span> <span class="token punctuation">{</span>
        $<span class="token punctuation">.</span>oc<span class="token punctuation">.</span><span class="token function">alert</span><span class="token punctuation">(</span>err<span class="token punctuation">.</span>message<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
    <span class="token keyword">finally</span> <span class="token punctuation">{</span>
        <span class="token keyword">this</span><span class="token punctuation">.</span>loadingButtonData <span class="token operator">=</span> <span class="token boolean">false</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Finally, the server-side handler must be added to the widget&#39;s PHP class. Ensure that the handler function name corresponds to the one specified in the client-side <code>request</code> call. Additionally, it should be a protected method that accepts both the widget configuration array and the extra data array.</p><div class="language-jsx extra-class"><pre class="language-jsx"><code><span class="token keyword">protected</span> <span class="token keyword">function</span> <span class="token function">onGetSomeData</span><span class="token punctuation">(</span><span class="token parameter">array $widgetConfig<span class="token punctuation">,</span> array $extraData</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string">&#39;result&#39;</span> <span class="token operator">=&gt;</span> <span class="token function">rand</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">)</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>Below is a screenshot of the widget displaying a random value received from the server:</p><p><img src="https://raw.githubusercontent.com/octobercms/docs/develop/images/dashboards/custom-widget-data.webp" alt="image"></p>`,24))])}const b=i(u,[["render",d]]);export{f as __pageData,b as default};
